// combo/rando/ComboGames.h
// ComboShip: OoTMM's "Games" setting — play both games (Combo), Ocarina of Time only, or Majora's Mask only.
// Header-only, compiled into the exe, soh.dll, 2ship.dll and comborando. See docs/deviations/rando.md
// "Games: OoT only / MM only / Combo".
//
// A solo seed is still generated by the combined fill over both games, but every item stays in its own game, the
// other game's checks only ever hold that game's own items, and nothing crosses over at runtime: the Happy Mask Shop
// and the Clock Tower door stay in their own game, cross-game teleports are refused, and the played game's final boss
// alone ends the run. Shared Items are off, the starting game is the played game, and every Triforce piece of a
// Triforce Hunt is in the played game.
#pragma once

#include <algorithm>
#include <string>

namespace ComboRando {

enum ComboGames {
    COMBO_GAMES_BOTH = 0, // OoTMM "ootmm"
    COMBO_GAMES_OOT = 1,  // OoTMM "oot"
    COMBO_GAMES_MM = 2,   // OoTMM "mm"
};

inline constexpr const char* kComboGamesCVar = "gCombo.Rando.Games";

inline ComboGames ComboGamesFromInt(int v) {
    return (v == COMBO_GAMES_OOT || v == COMBO_GAMES_MM) ? static_cast<ComboGames>(v) : COMBO_GAMES_BOTH;
}

inline bool ComboGamesSolo(ComboGames g) {
    return g != COMBO_GAMES_BOTH;
}

// Spoiler / save-container value (top-level "games"). Absent = "ootmm", so every older seed is a combo seed.
inline const char* ComboGamesKey(ComboGames g) {
    switch (g) {
        case COMBO_GAMES_OOT:
            return "oot";
        case COMBO_GAMES_MM:
            return "mm";
        default:
            return "ootmm";
    }
}
inline ComboGames ComboGamesFromKey(const std::string& s) {
    if (s == "oot")
        return COMBO_GAMES_OOT;
    if (s == "mm")
        return COMBO_GAMES_MM;
    return COMBO_GAMES_BOTH;
}

// The starting-game setting a seed actually uses (0 = OOT, 1 = MM, 2 = Random): a solo seed starts in its game.
inline int ComboGamesStartingGameCfg(ComboGames g, int cfg) {
    if (g == COMBO_GAMES_OOT)
        return 0;
    if (g == COMBO_GAMES_MM)
        return 1;
    return cfg;
}

// Triforce Hunt split. Combo: the combined total split evenly (OOT takes the odd piece). Solo: all of it in the
// played game, up to kMaxSoloTriforcePieces (what one game's pool is verified to hold, the combo split's 50/50).
// -1 (old seeds, no combined total) passes through so each game keeps its own slider.
inline constexpr int kMaxSoloTriforcePieces = 50;
inline int ComboGamesOotPieces(ComboGames g, int total) {
    if (total < 0)
        return -1;
    if (g == COMBO_GAMES_OOT)
        return std::min(total, kMaxSoloTriforcePieces);
    if (g == COMBO_GAMES_MM)
        return 0;
    return total - total / 2;
}
inline int ComboGamesMmPieces(ComboGames g, int total) {
    if (total < 0)
        return -1;
    if (g == COMBO_GAMES_MM)
        return std::min(total, kMaxSoloTriforcePieces);
    if (g == COMBO_GAMES_OOT)
        return 0;
    return total / 2;
}

} // namespace ComboRando
